import json
import subprocess
from pathlib import Path

def _lookup_wallet_label(keystore_path: Path) -> str:
    index_path = keystore_path.parent / 'wallet_index.json'
    if not index_path.is_file():
        return 'unknown'
    try:
        index_data = json.loads(index_path.read_text())
    except (OSError, ValueError):
        return 'unknown'
    return str(index_data.get(keystore_path.name, 'unknown'))

def wipe_wallet_keystore_and_run_shred(keystore_file_path: str, overwrite_pass_count: int=3) -> str:
    resolved_keystore_path = Path(keystore_file_path).expanduser().resolve()
    if not resolved_keystore_path.is_file():
        raise FileNotFoundError(f'Keystore file not found: {resolved_keystore_path}')
    if overwrite_pass_count < 1 or overwrite_pass_count > 35:
        raise ValueError('overwrite_pass_count must be between 1 and 35')
    wallet_label = _lookup_wallet_label(resolved_keystore_path)
    shred_command_arguments = ['shred', '-n', str(overwrite_pass_count), '-u', '-z', str(resolved_keystore_path)]
    completed_shred_process = subprocess.run(shred_command_arguments, capture_output=True, text=True, timeout=120)
    if completed_shred_process.returncode != 0:
        raise RuntimeError(f'shred failed with code {completed_shred_process.returncode}: {completed_shred_process.stderr.strip()}')
    return f'Shredded and removed {resolved_keystore_path} (wallet label: {wallet_label}) using {overwrite_pass_count} passes'
